// Define button pins according to schematic\nconst int BUTTON_KEY0 = 2;   // KEY0 - GPIO2\nconst int BUTTON_KEY1 = 3;   // KEY1 - GPIO3\nconst int BUTTON_KEY2 = 5;   // KEY2 - GPIO5\n\n// Button state variables\nbool lastKey0State = HIGH;\nbool lastKey1State = HIGH;\nbool lastKey2State = HIGH;\n\nvoid setup() {\n  // Initialize serial communication\n  Serial.begin(115200);\n  while (!Serial) {\n    delay(10); // Wait for serial port to connect\n  }\n\n  Serial.println("=================================");\n  Serial.println("Press any button to see output");\n  Serial.println();\n\n  // Configure button pins as inputs\n  // Hardware already has pull-up resistors, so use INPUT mode\n  pinMode(BUTTON_KEY0, INPUT_PULLUP);\n  pinMode(BUTTON_KEY1, INPUT_PULLUP);\n  pinMode(BUTTON_KEY2, INPUT_PULLUP);\n\n  // Read initial states\n  lastKey0State = digitalRead(BUTTON_KEY0);\n  lastKey1State = digitalRead(BUTTON_KEY1);\n  lastKey2State = digitalRead(BUTTON_KEY2);\n\n  Serial.println("Setup complete. Ready to detect button presses...");\n}\n\nvoid loop() {\n  // Read current button states\n  bool key0State = digitalRead(BUTTON_KEY0);\n  bool key1State = digitalRead(BUTTON_KEY1);\n  bool key2State = digitalRead(BUTTON_KEY2);\n\n  // Check KEY1\n  if (key0State != lastKey0State) {\n    if (key0State == LOW) {\n      Serial.println("KEY0 (GPIO2) pressed!");\n    } else {\n      Serial.println("KEY0 (GPIO2) released!");\n    }\n    lastKey0State = key0State;\n    delay(50); // Debounce delay\n  }\n\n  // Check KEY2\n  if (key1State != lastKey1State) {\n    if (key1State == LOW) {\n      Serial.println("KEY1 (GPIO3) pressed!");\n    } else {\n      Serial.println("KEY1 (GPIO3) released!");\n    }\n    lastKey1State = key1State;\n    delay(50); // Debounce delay\n  }\n\n  // Check KEY3\n  if (key2State != lastKey2State) {\n    if (key2State == LOW) {\n      Serial.println("KEY2 (GPIO5) pressed!");\n    } else {\n      Serial.println("KEY2 (GPIO5) released!");\n    }\n    lastKey2State = key2State;\n    delay(50); // Debounce delay\n  }\n\n  delay(10); // Small delay to prevent excessive CPU usage\n}\n'})}),"\n",(0,t.jsx)(n.p,{children:"\u4EE3\u7801\u89E3\u91CA\uFF1A"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:(0,t.jsx)(n.strong,{children:"\u6838\u5FC3\u51FD\u6570\u5206\u6790"})}),"\n"]}),"\n",(0,t.jsxs)(n.ol,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:(0,t.jsx)(n.code,{children:"pinMode(pin, mode)"})})}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"\u529F\u80FD\uFF1A\u914D\u7F6E\u5F15\u811A\u6A21\u5F0F\u3002"}),"\n",(0,t.jsxs)(n.li,{children:["\u8FD9\u91CC\u4F7F\u7528 ",(0,t.jsx)(n.code,{children:"INPUT_PULLUP"})," \u6A21\u5F0F\u6765\u542F\u7528\u5185\u90E8\u4E0A\u62C9\u7535\u963B\u3002\u8FD9\u4F7F\u5F97\u5F15\u811A\u5728\u6309\u94AE\u672A\u6309\u4E0B\u65F6\u9ED8\u8BA4\u8F93\u51FA\u9AD8\u7535\u5E73\uFF08HIGH\uFF09\uFF0C\u5F53\u6309\u94AE\u6309\u4E0B\u65F6\uFF08\u56E0\u4E3A\u8FDE\u63A5\u5230\u5730\uFF09\u8F93\u51FA\u4F4E\u7535\u5E73\uFF08LOW\uFF09\u3002"]}),"\n"]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsx)(n.p,{children:(0,t.jsx)(n.strong,{children:(0,t.jsx)(n.code,{children:"digitalRead(pin)"})})}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"\u529F\u80FD\uFF1A\u8BFB\u53D6\u6307\u5B9A\u5F15\u811A\u7684\u7535\u5E73\u72B6\u6001\uFF08HIGH \u6216 LOW\uFF09\u3002"}),"\n",(0,t.jsx)(n.li,{children:"\u5728\u5FAA\u73AF\u4E2D\u7528\u4E8E\u5B9E\u65F6\u83B7\u53D6\u6309\u94AE\u7684\u5F53\u524D\u72B6\u6001\uFF0C\u8FD9\u6709\u52A9\u4E8E\u5224\u65AD\u6309\u94AE\u662F\u5426\u88AB\u6FC0\u6D3B\u3002"}),"\n"]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:(0,t.jsx)(n.code,{children:"Serial.begin(baud)"})})," \u548C ",(0,t.jsx)(n.strong,{children:(0,t.jsx)(n.code,{children:"Serial.println()"})})]}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsx)(n.li,{children:"\u524D\u8005\u521D\u59C